INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Verschlüsselung eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt Daten"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Verschlüsselung?', 3, '[{"text": "Daten vor unbefugtem Zugriff schützen", "correct": true, "because": "Sichert Vertraulichkeit"}, {"text": "Daten löschen", "correct": false, "because": "Gegenteil"}, {"text": "Netzwerk beschleunigen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt Daten während der Übertragung. b) Sie ist nur für lokale Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Netzwerke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zur Verschlüsselung?', 4, '[{"text": "Symmetrische Verschlüsselung", "correct": true, "because": "Ein Schlüssel"}, {"text": "Unklare Methoden", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Asymmetrische Verschlüsselung", "correct": true, "because": "Zwei Schlüssel"}, {"text": "AES", "correct": true, "because": "Standardverfahren"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Verschlüsselung ohne Schlüssel funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Schlüssel nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Verschlüsselung im Datenschutz?', 3, '[{"text": "Sichert Vertraulichkeit von Daten", "correct": true, "because": "Schützt Privatsphäre"}, {"text": "Datenverfügbarkeit", "correct": false, "because": "Anderes Schutzziel"}, {"text": "Datenmanipulation", "correct": false, "because": "Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Verschlüsselung nur für Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Daten"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat symmetrische Verschlüsselung?', 3, '[{"text": "Daten mit einem Schlüssel verschlüsseln", "correct": true, "because": "Ein Schlüssel für beide Seiten"}, {"text": "Daten löschen", "correct": false, "because": "Andere Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Asymmetrische Verschlüsselung nutzt zwei Schlüssel. b) Sie ist immer schneller als symmetrische.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft langsamer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Verschlüsselung?', 3, '[{"text": "Daten können abgehört werden", "correct": true, "because": "Kein Schutz"}, {"text": "Daten schneller übertragen", "correct": false, "because": "Unsinn"}, {"text": "Daten sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Verschlüsselung ohne Authentifizierung bestehen?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängig möglich"}, {"text": "Nein", "correct": false, "because": "Ergänzt Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Verschlüsselungsmaßnahme?', 3, '[{"text": "HTTPS für Webseiten", "correct": true, "because": "Konkret und real"}, {"text": "Daten löschen", "correct": false, "because": "Keine Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Verschlüsselung nur für sensible Daten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten schützbar"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Verschlüsselung?', 4, '[{"text": "Schlüsselverwendung", "correct": true, "because": "Kernfunktion"}, {"text": "Unklare Daten", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Unlesbarkeit für Unbefugte", "correct": true, "because": "Schützt Inhalt"}, {"text": "Algorithmusbasiert", "correct": true, "because": "Mathematische Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Verschlüsselung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt AES bei der Verschlüsselung?', 3, '[{"text": "Standard für symmetrische Verschlüsselung", "correct": true, "because": "Weit verbreitet"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Verschlüsselung ohne Algorithmen arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Algorithmen nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gefährdet Verschlüsselung?', 3, '[{"text": "Schwache Schlüssel", "correct": true, "because": "Leicht zu knacken"}, {"text": "Hohe Netzwerkgeschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Gute Passwörter", "correct": false, "because": "Unterstützt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt vor Abhören. b) Sie ist nur für Hardware wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Verschlüsselung?', 3, '[{"text": "Datensicherheit gewährleisten", "correct": true, "because": "Schützt Vertraulichkeit"}, {"text": "Maximale Offenlegung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Sicherheit", "correct": false, "because": "Fördert Schutz"}]');